    "id": "must_take_cart",
    "text": "A shopper should obtain a shopping cart before completing the shopping trip.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "hasCart"
