  {
    "id": "exit_with_cart",
    "text": "A shopper must not leave the store without the shopping cart.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "hasCart"
          }
        ]
      }
    },
    "justification": "The rule is expressed in terms of the exit action and cart possession, which are meaningful in any supermarket layout."
