  {
    "id": "no_cart_in_single_file_shelf_aisle",
    "text": "A shopper should not take a cart into a single-file aisle flanked by shelves.",
    "abstraction": {
      "state_properties": {
        "vertical_single_file_shelf_aisle": {
          "and": [
            "shelfE",
            "shelfW",
            {
              "le": [
                "freeWidthH",
                2
