            }
          ]
        },
        "horizontal_single_file_shelf_aisle": {
          "and": [
            "shelfN",
            "shelfS",
            {
              "le": [
                "freeWidthV",
                2
              ]
            }
          ]
        },
        "single_file_shelf_aisle": {
          "or": [
            "vertical_single_file_shelf_aisle",
            "horizontal_single_file_shelf_aisle"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "single_file_shelf_aisle"
        ]
      }
    },
    "justification": "The abstraction uses local shelf adjacency and passage width, so it captures the same kind of aisle in different stores without naming coordinates."
  },
